<div class="tc-cs__grid tc-cs__grid--three"><?php $__currentLoopData = $controles; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $control): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); ?><article class="tc-cs__card tc-cs__control"><h2><i class="bi <?php echo e($control[2]); ?>"></i><?php echo e($control[0]); ?></h2><p class="tc-cs__hint"><?php echo e($control[1]); ?></p><dl class="tc-cs__list"><?php $__currentLoopData = $control[3]; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $fila): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); ?><div><dt><?php echo e($fila[0]); ?></dt><dd><?php echo e($fila[1]); ?></dd></div><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); ?></dl><span class="tc-cs__text-button" title="No existe configuración persistente para esta operación.">Sin entidad persistente <i class="bi bi-database-exclamation"></i></span></article><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); ?></div>
<div class="tc-cs__grid tc-cs__grid--wide tc-cs__section"><article class="tc-cs__card"><h2><i class="bi bi-bell"></i> Preferencias de alertas</h2><div class="tc-cs__empty"><i class="bi bi-bell"></i><p>El esquema no contiene reglas persistentes de alertas de seguridad.</p></div><span class="tc-cs__text-button" title="Falta una entidad persistente para preferencias de alertas.">Sin entidad persistente <i class="bi bi-database-exclamation"></i></span></article><article class="tc-cs__card"><h2><i class="bi bi-list-ul"></i> Actividad de seguridad reciente</h2><div class="tc-cs__table-wrap"><table><thead><tr><th>Acción</th><th>Entidad</th><th>Resultado</th><th>Fecha</th></tr></thead><tbody><?php $__empty_1 = true; $__currentLoopData = $eventos; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $evento): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); $__empty_1 = false; ?><tr><td><?php echo e($evento->accion); ?></td><td><?php echo e($evento->entidad); ?></td><td><?php echo e($evento->resultado ?: 'Sin resultado registrado'); ?></td><td><?php echo e($evento->creado_en); ?></td></tr><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); if ($__empty_1): ?><tr><td colspan="4">No hay eventos de seguridad en el alcance consultado.</td></tr><?php endif; ?></tbody></table></div><a href="<?php echo e(route('management.audit.preview.operations', ['modulo' => 'seguridad'])); ?>">Ver eventos de seguridad</a></article></div>
